function normalizeState(saved={}){const progress=saved.dunkingProgress||{},benchmarks=Object.fromEntries(Object.entries(benchmarkDefaults).map(([id,levels])=>[id,{...levels,...progress.benchmarks?.[id]}])),dunkGoal=saved.dunkGoal||{},measurement=(value,fallback)=>value!==null&&value!==undefined&&value!==""&&Number.isFinite(Number(value))?Number(value):fallback;return {...structuredClone(defaultState),...saved,customWorkouts:Array.isArray(saved.customWorkouts)?saved.customWorkouts:[],customExercises:Array.isArray(saved.customExercises)?saved.customExercises:[],workoutAdditions:Array.isArray(saved.workoutAdditions)?saved.workoutAdditions:[],settings:{...defaultState.settings,...saved.settings,durations:{...defaultState.settings.durations,...saved.settings?.durations},overrides:{...defaultState.settings.overrides,...saved.settings?.overrides},exerciseEdits:{...defaultState.settings.exerciseEdits,...saved.settings?.exerciseEdits}},trainingWeek:{...defaultState.trainingWeek,...saved.trainingWeek},dunkGoal:{...defaultState.dunkGoal,...dunkGoal,standingReachIn:measurement(dunkGoal.standingReachIn,null),rimHeightIn:measurement(dunkGoal.rimHeightIn,120),desiredClearanceIn:measurement(dunkGoal.desiredClearanceIn,6),currentVerticalIn:measurement(dunkGoal.currentVerticalIn,null),history:Array.isArray(dunkGoal.history)?dunkGoal.history:[]},dunkingProgress:{...structuredClone(defaultState.dunkingProgress),...progress,unit:progress.unit==="lb"?"lb":"kg",bodyweightEntries:Array.isArray(progress.bodyweightEntries)?progress.bodyweightEntries:[],liftEntries:Array.isArray(progress.liftEntries)?progress.liftEntries:[],benchmarks}};}
function loadState(){try{return normalizeState(JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}")||{});}catch{return structuredClone(defaultState);}}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
function toast(msg){const el=$("#toast");el.textContent=msg;el.classList.add("show");clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove("show"),2200);}
function fmt(sec){sec=Math.max(0,Math.floor(sec));return `${String(Math.floor(sec/60)).padStart(2,"0")}:${String(sec%60).padStart(2,"0")}`;}
function formatElapsed(sec){sec=Math.max(0,Math.floor(sec));const h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;}
function allWorkouts(){const library=allExercises();const builtins=workouts.map(workout=>({...workout,items:[...workout.items,...state.workoutAdditions.filter(addition=>addition.workoutId===workout.id).map(addition=>{const exercise=library.find(item=>item.id===addition.exerciseId);return exercise?{...exercise,section:addition.section||"Added exercises"}:null;}).filter(Boolean)]}));const custom=state.customWorkouts.map(workout=>({...workout,items:(workout.sections||[]).flatMap(section=>(section.exerciseIds||[]).map(id=>{const exercise=library.find(item=>item.id===id);return exercise?{...exercise,section:section.name,category:exercise.category||section.name}:null;})).filter(Boolean)}));return [...builtins,...custom];}
function allExercises(){const builtins=[...new Map(workouts.flatMap(w=>w.items).map(e=>[e.id,e])).values()];return [...builtins,...state.customExercises.map(e=>({...e,custom:true}))];}
function getRest(ex){return state.settings.overrides[ex.id]!==undefined&&state.settings.overrides[ex.id]!==""?Number(state.settings.overrides[ex.id]):Number(ex.restSeconds??state.settings.setRest);}
function exerciseSettings(ex){return {...ex,...(state.settings.exerciseEdits[ex.id]||{})};}
function repUnits(value){const matches=String(value).match(/\d+(?:\.\d+)?/g);return matches?.length?matches.map(Number).reduce((sum,n)=>sum+n,0)/matches.length:1;}
function estimatedExerciseMinutes(ex){const edit=state.settings.exerciseEdits[ex.id],sets=Math.max(1,Number(edit?.sets??ex.sets)||1),reps=repUnits(edit?.reps??ex.reps);if(Number.isFinite(Number(edit?.minutes))&&Number(edit.minutes)>0)return Math.max(0.1,Number(edit.minutes)*(sets*reps)/(Math.max(1,Number(edit.baseSets)||sets)*repUnits(edit.baseReps??reps)));const baseSets=Math.max(1,Number(ex.sets)||1),multiplier=weightedExerciseIds.has(ex.id)||ex.weighted?2:1.5;return Math.max(0.1,ex.minutes*multiplier*(sets*reps)/(baseSets*repUnits(ex.reps)));}
function saveExerciseEstimate(id){const source=allExercises().find(e=>e.id===id);if(!source)return;const setsInput=$(`[data-exercise-sets="${id}"]`),repsInput=$(`[data-exercise-reps="${id}"]`),minutesInput=$(`[data-exercise-minutes="${id}"]`),sets=Math.max(1,Math.min(30,Number(setsInput.value)||1)),reps=repsInput.value.trim(),minutes=Math.max(0.1,Math.min(600,Number(minutesInput.value)||estimatedExerciseMinutes(source)));if(!reps){toast("Enter the planned reps or hold duration.");return;}state.settings.exerciseEdits[id]={sets,reps,minutes,baseSets:sets,baseReps:reps};saveState();renderTimeline();updateProgress();renderWorkouts();renderDashboard();toast("Exercise estimate saved.");}
function estimatePlanFor(w){const plan=[];w.items.forEach((source,i)=>{const e=exerciseSettings(source),sets=Math.max(1,Number(e.sets)||1),workPerSet=Math.max(1,Math.round(estimatedExerciseMinutes(source)*60/sets));for(let s=1;s<=sets;s++){plan.push({exerciseId:source.id,seconds:workPerSet});if(s<sets){const rest=getRest(source);if(rest>0)plan.push({exerciseId:source.id,seconds:rest});}}if(i<w.items.length-1){const rest=Number(state.settings.exerciseRest)||0;if(rest>0)plan.push({exerciseId:w.items[i+1].id,seconds:rest});}});return plan;}
function durationFor(w){return estimatePlanFor(w).reduce((total,segment)=>total+segment.seconds,0);}
function weekStartDate(date=new Date()){const start=new Date(date.getFullYear(),date.getMonth(),date.getDate());start.setDate(start.getDate()-((start.getDay()+6)%7));return start;}
function dateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;}
function syncTrainingWeek(){const currentStart=weekStartDate(),currentKey=dateKey(currentStart),stored=state.trainingWeek.weekStart;if(!stored){state.trainingWeek.weekStart=currentKey;saveState();return;}const previousStart=new Date(`${stored}T00:00:00`);if(!Number.isFinite(previousStart.getTime())){state.trainingWeek.weekStart=currentKey;saveState();return;}const weeks=Math.round((currentStart-previousStart)/604800000);if(weeks>0){if(weeks%2)state.trainingWeek.current=state.trainingWeek.current==="A"?"B":"A";state.trainingWeek.weekStart=currentKey;saveState();}}
function nav(view){$$(".view").forEach(v=>v.classList.remove("active"));const el=$("#"+view+"-view");if(el)el.classList.add("active");$$(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===view));$("#page-title").textContent=({dashboard:"Dashboard",workouts:"Workouts",builder:"Workout Builder",session:"Active session",history:"History",progress:"Dunking Progress",settings:"Settings"})[view]||"Dashboard";$(".sidebar").classList.remove("open");if(view==="progress")renderDunkingProgress();if(view==="builder")renderBuilder();window.scrollTo({top:0,behavior:"smooth"});}
function workoutCard(w){return `<article class="workout-card"><div class="card-top"><span class="day-tag">${escapeHtml(w.day||"Unscheduled")} · ${escapeHtml((w.type||"CUSTOM").split("·")[0].trim())}</span><span class="card-icon">${escapeHtml(w.icon||"◇")}</span></div><h3>${escapeHtml(w.title)}</h3><p>${escapeHtml(w.subtitle||"Custom workout")}</p><div class="card-bottom"><span>${w.items.length} exercises · ${Math.round(durationFor(w)/60)} min est.</span><button data-start="${w.id}">Open session ↗</button></div></article>`;}
function formatInches(value){return `${Number(value.toFixed(1))}"`;}
