function startWorkout(id){const selected=allWorkouts().find(w=>w.id===id);if(!selected)return;if(timer.running&&currentWorkout){if(currentWorkout.id!==id)toast("Finish or reset the active session before starting another workout.");nav("session");return;}currentWorkout=selected;completed=new Set();expanded=new Set();resetTimer(false);$("#session-day-label").textContent=(currentWorkout.day||"UNSCHEDULED")+" · "+(currentWorkout.type||"CUSTOM WORKOUT");$("#session-title").textContent=currentWorkout.title;$("#session-subtitle").textContent=currentWorkout.subtitle||"Your custom workout.";renderTimeline();updateProgress();updateTimerPanel();nav("session");}
