function elapsedSeconds(){if(!timer.running||!timer.startedAt)return timer.elapsed;timer.elapsed=Math.max(timer.elapsed,timer.elapsedBase+Math.max(0,Math.floor((Date.now()-timer.startedAt)/1000)));return timer.elapsed;}
