function renderBuilder(){}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));}
function toKg(value,unit){return Number(value)*(unit==="lb"?0.45359237:1);}
