function formatLoad(value,unit){return `${Number(value).toFixed(1)} ${unit}`;}
function sortedByDate(entries){return [...entries].sort((a,b)=>a.date.localeCompare(b.date)||(a.createdAt||a.id||"").toString().localeCompare((b.createdAt||b.id||"").toString()));}
