document.addEventListener("click",e=>{
 const view=e.target.closest("[data-view]");if(view){nav(view.dataset.view);return;}
 const start=e.target.closest("[data-start]");if(start){startWorkout(start.dataset.start);return;}
 const done=e.target.closest("[data-complete]");if(done){completeExercise(done.dataset.complete);return;}
 const expand=e.target.closest("[data-expand]");if(expand){const id=expand.dataset.expand;expanded.has(id)?expanded.delete(id):expanded.add(id);renderTimeline();return;}
 const saveExercise=e.target.closest("[data-save-exercise]");if(saveExercise){saveExerciseEstimate(saveExercise.dataset.saveExercise);return;}
 const override=e.target.closest("[data-save-override]");if(override){saveOverride(override.dataset.saveOverride);return;}
 const log=e.target.closest("[data-save-log]");if(log){saveLog(log.dataset.saveLog);return;}
 const bodyweightEdit=e.target.closest("[data-edit-bodyweight]");if(bodyweightEdit){editBodyweight(bodyweightEdit.dataset.editBodyweight);return;}
 const liftEdit=e.target.closest("[data-edit-lift]");if(liftEdit){editLift(liftEdit.dataset.editLift);return;}
});
