 const id=input.dataset.exerciseSets||input.dataset.exerciseReps,minutes=$(`[data-exercise-minutes="${id}"]`),setsInput=$(`[data-exercise-sets="${id}"]`),repsInput=$(`[data-exercise-reps="${id}"]`),baseSets=Math.max(1,Number(minutes.dataset.baseSets)||1),baseReps=repUnits(minutes.dataset.baseReps),sets=Math.max(1,Number(setsInput.value)||1),reps=repUnits(repsInput.value);
